INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('신경증(neurosis)의 특징으로 옳은 것은?' || char(10) || 'A. 환각이나 망상 등 현실 왜곡 증상이 두드러진다' || char(10) || 'B. 현실판단력이 정상적이며 자기통찰이 있다' || char(10) || 'C. 사회적 적응에 심각한 곤란을 겪는다' || char(10) || 'D. 자기통찰이 없어 입원치료가 필요하다', 'B', 'multiple-choice', 'subnote', 2, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('정신증(psychosis)의 특징으로 옳은 것은?' || char(10) || 'A. 자기통찰이 있어 외래치료가 가능하다' || char(10) || 'B. 현실판단력이 정상적이다' || char(10) || 'C. 환각이나 망상과 같은 현실 왜곡적 증상이 두드러진다' || char(10) || 'D. 경미한 부적응만 보인다', 'C', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('범주적 분류의 특징으로 옳은 것은?' || char(10) || 'A. 정상과 이상의 구분은 정도의 문제이다' || char(10) || 'B. 양적인 차이만 존재한다고 본다' || char(10) || 'C. 연속선상에서 범위로 분류한다' || char(10) || 'D. 이상행동이 정상행동과 질적으로 구분된다고 본다', 'D', 'multiple-choice', 'subnote', 2, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('차원적 분류의 특징으로 옳은 것은?' || char(10) || 'A. 흑백논리적으로 분류한다' || char(10) || 'B. 정상행동과 이상행동의 구분이 부적응성의 정도 문제이다' || char(10) || 'C. 이상행동은 정상행동과 질적으로 구분된다' || char(10) || 'D. 명료한 차이가 존재한다고 본다', 'B', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('강박사고에 대한 설명으로 옳은 것은?' || char(10) || 'A. 반복적으로 의식에 침투하는 고통스러운 생각, 충동 또는 심상' || char(10) || 'B. 강박사고로 인한 불안을 감소시키기 위한 반복적 행동' || char(10) || 'C. 의식적으로 떠올리는 긍정적 사고' || char(10) || 'D. 특정 대상에 대한 극심한 공포 반응', 'A', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('강박행동에 대한 설명으로 옳은 것은?' || char(10) || 'A. 무의식적 갈등에 의한 자발적 행동' || char(10) || 'B. 반복적으로 의식에 침투하는 고통스러운 생각' || char(10) || 'C. 특정 상황에서의 회피 행동' || char(10) || 'D. 강박사고로 인한 불안을 감소시키기 위해 반복적으로 나타내는 행동', 'D', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
