INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('Seligman의 준비성(preparedness)에 대한 설명으로 옳은 것은?' || char(10) || 'A. 생존을 위협하는 자극에는 공포반응을 더 쉽게 학습하는 생물학적 성향' || char(10) || 'B. 무의식적 갈등이 공포의 유일한 원인이다' || char(10) || 'C. 모든 자극에 대해 동일한 확률로 공포를 학습한다' || char(10) || 'D. 공포 반응은 전적으로 학습에 의해서만 결정된다', 'A', 'multiple-choice', 'subnote', 2, 13, '', datetime('now'));
