INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''하위유형 ①강박장애''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 불안을유발하는강박사고나강박행동이나타나며,이로인해시간을소모함 ② 신체이형장애:하나 이상의 미미한 신체적 ' || char(10) || 'B. 비윤리적생각은그러한행위를한것과도덕적으로다르지않다. ②발생가능성융합:비윤리적생각을하면실제로행위할가능성이높아' || char(10) || 'C. 내면적인강박사고만지니는경우' || char(10) || 'D. 겉으로관찰되지않는내면적강박행동(예숫자세기,단어암기)', 'A', 'multiple-choice', 'subnote', 2, 13, '', datetime('now'));
