INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''핵심증상''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 불안을유발하는강박사고나강박행동이나타나며,이로인해시간을소모함 ①강박사고:반복적으로의식에침투하는고통스러운생' || char(10) || 'B. 항문기적 성격의 인색함반영 ② 대상관계:전이대상☞어린아이가 독립성을 발달시키는 과정에서 부모를 대신' || char(10) || 'C. 미해결된아동기의정서적문제,특히권위적인부모에대한억압된분노의표현 ②인지행동:일종의스트레스대처방식(자기-진정' || char(10) || 'D. 우연한 사건에 의해 신체적 증상에 주목,미적 민감성으로 인한 비판적 평가 =>신체상에대한부정적평가(Ve', 'A', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
