INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('양극성 및 관련 장애에서 ''조증삽화(일주일)±주요우울삽화(2주) ② 제Ⅱ형 양극성장애:주요우울삽화(2주)+경조증삽화(4일) ③ 순환성장애:경조증 +우울증 /...''에 해당하는 것은?' || char(10) || 'A. 정신분석' || char(10) || 'B. 대인관계및사회적리듬치료' || char(10) || 'C. 하위유형 ①제Ⅰ형양극성장애' || char(10) || 'D. 인지적입장', 'C', 'multiple-choice', 'subnote', 2, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''하위유형 ①제Ⅰ형양극성장애''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 인지적왜곡⇒긍정적인왜곡을통해서자신과미래에대한비현실적인긍정적생각을 하게됨 4.양극성장애의 치료' || char(10) || 'B. 조증삽화(일주일)±주요우울삽화(2주) ② 제Ⅱ형 양극성장애:주요우울삽화(2주)+경조증삽화(4일) ' || char(10) || 'C. 비정상적으로들뜨거나,의기양양하거나,과민한기분,그리고활동과에너지의증가 가적어도4일연속으로거의매일,' || char(10) || 'D. 가족의지지등현실적응돕기', 'B', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('양극성 및 관련 장애에서 ''비정상적으로들뜨거나,의기양양하거나,과민한기분,그리고목표지향적활동과에 너지의증가가적어도일주일간(만약입원이필요할정도라면기간과상관없이)거의매...''에 해당하는 것은?' || char(10) || 'A. 하위유형 ①제Ⅰ형양극성장애' || char(10) || 'B. 경조증삽화' || char(10) || 'C. 인지행동치료' || char(10) || 'D. 조증삽화', 'D', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
