INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('양극성 및 관련 장애에서 ''비정상적으로들뜨거나,의기양양하거나,과민한기분,그리고활동과에너지의증가 가적어도4일연속으로거의매일,하루중대부분지속되는분명한기간이있다. ...''에 해당하는 것은?' || char(10) || 'A. 대인관계및사회적리듬치료' || char(10) || 'B. 인지행동치료' || char(10) || 'C. 경조증삽화' || char(10) || 'D. 인지적입장', 'C', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
