INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('양극성 및 관련 장애에서 ''조증 증세를무의식적 상실이나 자존감 손상에 대한 방어나 보상 반응으로 봄''에 해당하는 것은?' || char(10) || 'A. 약물치료' || char(10) || 'B. 인지행동치료' || char(10) || 'C. 정신분석' || char(10) || 'D. 경조증삽화', 'C', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''정신분석''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 부정적경험의인지적재구성,규칙적인일상생활과수면을유지하는것의중요성 강조,과도한목표추구행동수정' || char(10) || 'B. 조증삽화시입원치료와약물치료(리튬등항조증약물)' || char(10) || 'C. 조증 증세를무의식적 상실이나 자존감 손상에 대한 방어나 보상 반응으로 봄' || char(10) || 'D. 대인관계의안정과사회적일상생활의규칙성돕기 10조현병 스펙트럼 및 기타 정신병적 장애', 'C', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
