INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('양극성 및 관련 장애에서 ''조증삽화시입원치료와약물치료(리튬등항조증약물)''에 해당하는 것은?' || char(10) || 'A. 약물치료' || char(10) || 'B. 하위유형 ①제Ⅰ형양극성장애' || char(10) || 'C. 경조증삽화' || char(10) || 'D. 심리치료', 'A', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''약물치료''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 가족의지지등현실적응돕기' || char(10) || 'B. 조증삽화시입원치료와약물치료(리튬등항조증약물)' || char(10) || 'C. 대인관계의안정과사회적일상생활의규칙성돕기 10조현병 스펙트럼 및 기타 정신병적 장애' || char(10) || 'D. 부정적경험의인지적재구성,규칙적인일상생활과수면을유지하는것의중요성 강조,과도한목표추구행동수정', 'B', 'multiple-choice', 'subnote', 2, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('원인 및 치료에서 ''다른사람의동기를악의가있는것으로해석하는등타인에대한전반적인불신과 의심양상 ① 정신분석 입장 ⓐ프로이트:동성애적욕구에대한불안을제거하기위한방어기...''에 해당하는 것은?' || char(10) || 'A. 자기애성성격장애' || char(10) || 'B. 강박성성격장애' || char(10) || 'C. 반사회성 성격장애' || char(10) || 'D. 편집성 성격장애', 'D', 'multiple-choice', 'subnote', 2, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''편집성 성격장애''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 돌봄을받고자하는지나친욕구가복종적이고매달리는행동유발양상 ① 선천적 신체조건으로 보호반응 유발 및 의존적 성향' || char(10) || 'B. 다른사람의동기를악의가있는것으로해석하는등타인에대한전반적인불신과 의심양상 ① 정신분석 입장 ⓐ프로이트:동' || char(10) || 'C. 사회적유대로부터유리되고,제한된범위의감정표현양상 ① 정신분석 ⓐ카메론:기본적신뢰의결여 ⓑ발린트:타' || char(10) || 'D. 사회관계의억제,부적절감,그리고부정적평가에대한예민함 ① 생물학적 입장:수줍고억제적인기질,위험에 대한', 'B', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('원인 및 치료에서 ''사회적유대로부터유리되고,제한된범위의감정표현양상 ① 정신분석 ⓐ카메론:기본적신뢰의결여 ⓑ발린트:타인과관계맺는능력의결함 ② 인지적입장:...''에 해당하는 것은?' || char(10) || 'A. 조현성 성격장애' || char(10) || 'B. 강박성성격장애' || char(10) || 'C. 조현형 성격장애' || char(10) || 'D. 의존성성격장애', 'A', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''조현성 성격장애''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 사회적유대로부터유리되고,제한된범위의감정표현양상 ① 정신분석 ⓐ카메론:기본적신뢰의결여 ⓑ발린트:타' || char(10) || 'B. 과대성(공상또는행동상),숭배에의요구,공감의부족양상 ① 정신분석 입장:성장하면서 사랑의 대상이 자신에게' || char(10) || 'C. 친분관계를급작스럽게불편해하고그럴능력의감퇴및인지및지각의왜곡,행 동의괴이성양상 ① 정신분석:유아기에 경험' || char(10) || 'D. 정돈,완벽,그리고조절에지나치게집착 ① 정신분석 입장:심리성적 발달단계의 항문기경험과 관련,과잉통제', 'A', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('원인 및 치료에서 ''친분관계를급작스럽게불편해하고그럴능력의감퇴및인지및지각의왜곡,행 동의괴이성양상 ① 정신분석:유아기에 경험한 부모와의 불안정한 애착관계에 기인...''에 해당하는 것은?' || char(10) || 'A. 편집성 성격장애' || char(10) || 'B. 회피성성격장애' || char(10) || 'C. 연극성성격장애' || char(10) || 'D. 조현형 성격장애', 'D', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''조현형 성격장애''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 대인관계,자아상및정동불안정성과현저한충동성양상 ① 정신분석:오이디푸스 갈등 이전의 어린 시절에 어머니와' || char(10) || 'B. 사회관계의억제,부적절감,그리고부정적평가에대한예민함 ① 생물학적 입장:수줍고억제적인기질,위험에 대한' || char(10) || 'C. 사회적유대로부터유리되고,제한된범위의감정표현양상 ① 정신분석 ⓐ카메론:기본적신뢰의결여 ⓑ발린트:타' || char(10) || 'D. 친분관계를급작스럽게불편해하고그럴능력의감퇴및인지및지각의왜곡,행 동의괴이성양상 ① 정신분석:유아기에 경험', 'D', 'multiple-choice', 'subnote', 3, 13, '', datetime('now'));
