INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('사이버상담에서 ''이메일 상담,게시판 상담,데이터베이스 상담,채팅 상담,화상 상담''에 해당하는 것은?' || char(10) || 'A. 사이버상담의 유형' || char(10) || 'B. 해석' || char(10) || 'C. 표현 기법' || char(10) || 'D. 호소문제 유형', 'A', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
