INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('사이버상담에서 ''내담자의 요구 파악하기,제목 정하기,맞이하기,호소문제 명료화하기,공감하기,내 담자의 강점 지지하기,상담목표 설정하기,격려하기,추...''에 해당하는 것은?' || char(10) || 'A. 표현 기법' || char(10) || 'B. 상담과정1' || char(10) || 'C. 경청' || char(10) || 'D. 요약', 'B', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''상담과정1''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자가 말한 내용에서 감정과 관련된 부분을 바꾸어 말하는 것 한 바를 상담자가 정확히 지각하였는지 확인하' || char(10) || 'B. 내담자의 요구 파악하기,제목 정하기,맞이하기,호소문제 명료화하기,공감하기,내 담자의 강점 지지하기' || char(10) || 'C. 내담자가 말한 내용을 다시 한 번 반복해 주는 것으로,상담자가 내담자를 이해하고' || char(10) || 'D. 생략된 정보를 보완하고 내담자 말의 의미를 구체화하고자 할 때 사용', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담의에서 ''내담자와의 약속과 진실에 충실한 것으로 이는 상담자와 내담자 간에 신뢰를 이끌어 들은 서비스를 동등하게 받을 권리가 있다.''에 해당하는 것은?' || char(10) || 'A. 비유해성(무해성)' || char(10) || 'B. 선의' || char(10) || 'C. 자율성 존중' || char(10) || 'D. 충실성', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''충실성''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자와의 약속과 진실에 충실한 것으로 이는 상담자와 내담자 간에 신뢰를 이끌어 들은 서비스를 동등하게 받' || char(10) || 'B. 내담자는 자신의 행동을 스스로 결정하고 처리할 수 있는 자율적 존재이므로,' || char(10) || 'C. 상담자는 인종,성별,종교를 이유로 내담자를 차별하지 말아야 한다.모든 사람 부정직한 사람은 내담자의 ' || char(10) || 'D. 상담자는 다른 사람에게 손해를 주거나 해를 입히거나 위험에 빠뜨리지 않 상담자는 내담자가 자기 행동에 책임', 'A', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담의에서 ''상담자는 인종,성별,종교를 이유로 내담자를 차별하지 말아야 한다.모든 사람 부정직한 사람은 내담자의 성장이나 복지에 아무런 도움을 줄 수...''에 해당하는 것은?' || char(10) || 'A. 자율성 존중' || char(10) || 'B. 선의' || char(10) || 'C. 공정성(정의)' || char(10) || 'D. 충실성', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
