INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담의에서 ''상담자는 다른 사람에게 선행을 베풀겠다는 의도를 가지고 행동해야 한다.무능하거나 인한 후에 개입해야 함을 의미한다. 할 의무로,상담자들이 ...''에 해당하는 것은?' || char(10) || 'A. 공정성(정의)' || char(10) || 'B. 선의' || char(10) || 'C. 비유해성(무해성)' || char(10) || 'D. 자율성 존중', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
