INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''즉시성''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 상담자가 자신의 생각,가치,느낌,태도 등 여러 가지 정보를 내담자에게 드러내 보이는 것' || char(10) || 'B. 효과적으로 다른 사람에게 자신의 감정과 생각을 전달하는 방법(3요소:행동,영향, 감정) 4상담의' || char(10) || 'C. 상담 순간에 느껴지는 상담자 자신의 감정과 직관을 내담자에게 내놓음으로써 내담자 에게 새로운 안목을 제공하' || char(10) || 'D. 사람,활동,행사,자원,대안,결과나 절차에 관한 자료 또는 사실을 말로 전달해 주는 것', 'C', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
