INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''생활양식 ① 생활양식''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자의 초기 회상,가족구도,기본적 오류,꿈 등을 통하여 내담자에 대한 평가 및 분석이 이루어진다.' || char(10) || 'B. ‘성격’과 유사한 개념.인생의 목표를 달성하기 위하여 개인이 지닌 특성 ② 열등감을 보상하기 위한 행동으' || char(10) || 'C. 자신의 잘못된 목표와 신념을 회피하지 않고 정면으로 자각하도록 하는 것 ☞주관적 견해,잘못된 신념' || char(10) || 'D. 초기 어린 시절(생후 6개월부터 8세)에 경험한 사건에 대한 선별된 기억', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('주요개념에서 ''자기완성을 위한 필수요인이자 모든 노력의 근원(긍정적인 측면)이다. ② 열등감과 우월성 추구 ⓐ열등감을 극복하고 완성에 도달하기 위해 우월성...''에 해당하는 것은?' || char(10) || 'A. 초기회상' || char(10) || 'B. 열등감 ① 열등감' || char(10) || 'C. 좋은 상담관계형성' || char(10) || 'D. 출생순위 분석', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''열등감 ① 열등감''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자가 스스로 할 수 없다고 생각하는 것을 실제로 성취할 수 있는 것처럼 행동해보도록 권장하는 개입방법' || char(10) || 'B. 내담자의 진술에 대한 해석을 하는 단계로 자기이해와 통찰을 촉 진한다.해석을 바탕으로 자신의 잘못된 목표' || char(10) || 'C. 해석을 통한 내담자의 통찰을 실제 행동으로 전환시키는 과정으로 내담자가 새로운 방향을 갖도록 조력하는 단계' || char(10) || 'D. 자기완성을 위한 필수요인이자 모든 노력의 근원(긍정적인 측면)이다. ② 열등감과 우월성 추구 ⓐ열등감을 ', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
