INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''조건화''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 어떤 자극들 간의 연합이 다른 자극들 간의 연합보다 더 잘 이루어지는 경향' || char(10) || 'B. 자극과 반응이 연관을 갖도록 만드는 것(욕구조건화와 혐오조건화)' || char(10) || 'C. 서로 양립하기 어려운 반응을 유발하는 자극을 포함하는 고전적 조건형성 절차를 사용하여 이전 조건형성의 원치' || char(10) || 'D. 한 조건형성 경험에서 조건자극이었던 자극을 새로운 중성자극과 짝을 지어서 두 번째 조건 자극을 만들어내는 ', 'B', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('강화에서 ''특정한 반응이 일어날 확률을 증가시키는 것''에 해당하는 것은?' || char(10) || 'A. 강화계획 Ÿ 부분강화,간헐강화' || char(10) || 'B. 연속강화와 차별강화 ① 연속강화' || char(10) || 'C. 강화의 원리' || char(10) || 'D. 강화', 'D', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''강화''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 특정한 반응이 일어날 확률을 증가시키는 것' || char(10) || 'B. 어떤 행동이 일어날 때마다 강화가 주어지는 것 ② 차별강화:행동수정에서 특정 행동의 빈도를 증가시키기 위' || char(10) || 'C. 바람직한 행동을 증가시키기 위하여 환경적 자극을 주는 것 ② 부적 강화:내담자가 바람직한 행동을 할 때,' || char(10) || 'D. 즉시강화의 원리,일관성의 원리,점진적접근의 원리', 'A', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('강화에서 ''즉시강화의 원리,일관성의 원리,점진적접근의 원리''에 해당하는 것은?' || char(10) || 'A. 강화' || char(10) || 'B. 연속강화와 차별강화 ① 연속강화' || char(10) || 'C. 강화의 원리' || char(10) || 'D. 강화계획 Ÿ 부분강화,간헐강화', 'C', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''강화의 원리''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 반응이 일어날 때마다 강화를 제공하지 않고 어떤 기준에 따라 일정 한 시간 간격을 두고 표적행동이 나타나거' || char(10) || 'B. 즉시강화의 원리,일관성의 원리,점진적접근의 원리' || char(10) || 'C. 바람직한 행동을 증가시키기 위하여 환경적 자극을 주는 것 ② 부적 강화:내담자가 바람직한 행동을 할 때,' || char(10) || 'D. 어떤 행동이 일어날 때마다 강화가 주어지는 것 ② 차별강화:행동수정에서 특정 행동의 빈도를 증가시키기 위', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
