INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''강화와 처벌 ① 정적 강화''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 바람직한 행동을 증가시키기 위하여 환경적 자극을 주는 것 ② 부적 강화:내담자가 바람직한 행동을 할 때,' || char(10) || 'B. 어떤 행동이 일어날 때마다 강화가 주어지는 것 ② 차별강화:행동수정에서 특정 행동의 빈도를 증가시키기 위' || char(10) || 'C. 특정한 반응이 일어날 확률을 증가시키는 것' || char(10) || 'D. 반응이 일어날 때마다 강화를 제공하지 않고 어떤 기준에 따라 일정 한 시간 간격을 두고 표적행동이 나타나거', 'A', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
