INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('강화에서 ''반응이 일어날 때마다 강화를 제공하지 않고 어떤 기준에 따라 일정 한 시간 간격을 두고 표적행동이 나타나거나 일정한 빈도로 표적행동이 나타났을...''에 해당하는 것은?' || char(10) || 'A. 강화와 처벌 ① 정적 강화' || char(10) || 'B. 연속강화와 차별강화 ① 연속강화' || char(10) || 'C. 강화' || char(10) || 'D. 강화계획 Ÿ 부분강화,간헐강화', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''강화계획 Ÿ 부분강화,간헐강화''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 특정한 반응이 일어날 확률을 증가시키는 것' || char(10) || 'B. 반응이 일어날 때마다 강화를 제공하지 않고 어떤 기준에 따라 일정 한 시간 간격을 두고 표적행동이 나타나거' || char(10) || 'C. 바람직한 행동을 증가시키기 위하여 환경적 자극을 주는 것 ② 부적 강화:내담자가 바람직한 행동을 할 때,' || char(10) || 'D. 즉시강화의 원리,일관성의 원리,점진적접근의 원리', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''아동이 한 번도 해 본 적이 없거나 거의 하지 않는 어떤 새로운 행동을 가르치려고 할 때 효과적인 기법으로,조성하고자 하는 최종 목표를 세워...''에 해당하는 것은?' || char(10) || 'A. 반응대가' || char(10) || 'B. 행동조성' || char(10) || 'C. 역할극' || char(10) || 'D. 자기주장훈련', 'B', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''행동조성''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 문제행동을 충족시켜 줄 수 있는 그 이상의 자극을 훨씬 넘도록 줌으로써 내담자 로 하여금 질려버리게 하여 ' || char(10) || 'B. 목표행동에 따른 강화계획에 대하여 상담자와 내담자가 동의한 내용을 문서로 작성 하는 것' || char(10) || 'C. 바람직하지 못한 행동을 하였을 때 그 행동에 대한 대가로 이미 주어진 정적 강화를 상실하게 하는 것' || char(10) || 'D. 아동이 한 번도 해 본 적이 없거나 거의 하지 않는 어떤 새로운 행동을 가르치려고 할 때 효과적인 기법으로', 'D', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''연속적인 시도를 통해 반응을 통제하는 자극을 점진적으로 변화시킴으로써 적절한 행 동을 발달시키는 행동치료 방법''에 해당하는 것은?' || char(10) || 'A. 역할극' || char(10) || 'B. 행동계약' || char(10) || 'C. 반응대가' || char(10) || 'D. 용암법', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''용암법''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 불안과 불안이 없는 상태는 공존하지 못한다는 상호제지의 이론을 바탕으로, 자극과 불안반응의 조건형성을 깨' || char(10) || 'B. 긍정적 강화를 얻을 수 있는 환경으로부터 격리시켜 문제행동을 감소시키는 방법' || char(10) || 'C. 현실보다 과장된 형태로 불안을 유발하는 심상을 계속적으로 제시함으로써 불 안반응을 감소시키는 방법' || char(10) || 'D. 연속적인 시도를 통해 반응을 통제하는 자극을 점진적으로 변화시킴으로써 적절한 행 동을 발달시키는 행동치료 ', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''계획된 프로그램을 실시하여 기대행동이 일어날 때 아동에게 토큰(스티 커,딱지 등)을 주어 소정의 행동이행 점수가 성취되면 후속 강화제인 음식...''에 해당하는 것은?' || char(10) || 'A. 자기주장훈련' || char(10) || 'B. 모델링' || char(10) || 'C. 토큰강화(환표이용법)' || char(10) || 'D. 체계적 둔감법', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''토큰강화(환표이용법)''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 계획된 프로그램을 실시하여 기대행동이 일어날 때 아동에게 토큰(스티 커,딱지 등)을 주어 소정의 행동이행' || char(10) || 'B. 문제를 일으키는 자극 또는 강화물을 얻을 수 있는 기회로부터 제외시키는 것으로 정적 강화의 접근을 일정 시' || char(10) || 'C. 내담자의행동수정을위해내담자의잘못인지된인지구조를수정하는것' || char(10) || 'D. 상대방의 권리를 침해하거나 불쾌하게 하지 않는 범위 내에 자신을 나타낼 수 있도록 학습하는 것', 'A', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''긍정적 강화를 얻을 수 있는 환경으로부터 격리시켜 문제행동을 감소시키는 방법''에 해당하는 것은?' || char(10) || 'A. 과잉교정' || char(10) || 'B. 격리' || char(10) || 'C. 모델링' || char(10) || 'D. 인지행동수정', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''격리''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자에게 강한 불안을 유발하는 자극이나 심상을 노출시키고 불안이 감소될 때까지 노출을 계속하는 방법' || char(10) || 'B. 내담자에게 불쾌감을 연상시켜 바람직하지 않은 행동을 소거하는 방법' || char(10) || 'C. 긍정적 강화를 얻을 수 있는 환경으로부터 격리시켜 문제행동을 감소시키는 방법' || char(10) || 'D. 계획된 프로그램을 실시하여 기대행동이 일어날 때 아동에게 토큰(스티 커,딱지 등)을 주어 소정의 행동이행', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''바람직하지 않은 행동에 대한 책임을 강제로 지게 하기 위하여 특정 행동을 지나칠 정도로 반복하여 시행시킴으로써 문제 행동을 수정하는 것''에 해당하는 것은?' || char(10) || 'A. 홍수법' || char(10) || 'B. 과잉교정' || char(10) || 'C. 자극포화법' || char(10) || 'D. 격리', 'B', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
