INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''질문하기''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자로 하여금 자신의 삶을 스스로 통제할 수 있으며 자신의 행동을 선택할 수 있다는 인식을 심어주기 위하' || char(10) || 'B. 담자가 내담자와 질문을 주고받는 가운데 내담자의 대답이 현실성이 없는 등 합 리적이지 못할 경우,상담자는' || char(10) || 'C. 현실치료는 WDEP모델의 각단계마다 상담자가 내담자에게 던질 수 있는 다양한 물음들을 구체적으로 제시한' || char(10) || 'D. 내담자의 통제감과 책임감을 증진하기 위해 활용한다.계획을 세우고 실천하는 것에 대해서 저항할 수 있는 내', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
