INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''동사로 표현하기''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자로 하여금 자신의 삶을 스스로 통제할 수 있으며 자신의 행동을 선택할 수 있다는 인식을 심어주기 위하' || char(10) || 'B. 내담자와 편안하고 친밀한 관계를 맺는 데 도움이 되며,치료과정에서 재미와 즐거 움의 욕구 충족 효과가 있' || char(10) || 'C. 내담자의 통제감과 책임감을 증진하기 위해 활용한다.계획을 세우고 실천하는 것에 대해서 저항할 수 있는 내' || char(10) || 'D. 내담자의 은유적 표현에는 많은 정보가 담겨 있으므로 주의를 기울이 며,동시에 은유적 표현을 통해서 내담자', 'A', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''부정적인 것을 줄이기보다 긍정적인 것을 늘리는 데 초점을 맞추는 것이 다.‘어리석은 행동하지 않기’보다 ‘현명한 행동하기’에 초점을 맞춤으로...''에 해당하는 것은?' || char(10) || 'A. 은유적 표현사용하기' || char(10) || 'B. 토의와 논쟁' || char(10) || 'C. 질문하기' || char(10) || 'D. 긍정적으로 접근하기', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
