INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''편향''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 개체가자신에대해지나치게의식하고관찰하는현상' || char(10) || 'B. 타인의신념과기준을자신과조화되도록동화시키지못한채무비판적으로수용하려는경향' || char(10) || 'C. 자신의생각이나욕구,감정등을타인의것으로지각하는현상으로책임소재를타인에게돌리 는것' || char(10) || 'D. 감당하기힘든심리적결과가예상되거나이런경험으로부터압도당하지않기위해환경과의 접촉을피해버리거나자신의감각을둔화시켜버', 'D', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('성격 변화 단계에서 ''사람들이서로형식적․의례적규범에따라피상적으로만나는단계''에 해당하는 것은?' || char(10) || 'A. 내파층(내부파열층)' || char(10) || 'B. 폭발층(외파층)' || char(10) || 'C. 교착층(난국층,막다른 골목)' || char(10) || 'D. 피상층', 'D', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''피상층''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 자신의감정과욕구를더이상억압하거나차단하지않고직접외부대상에게표현 하는단계→게슈탈트와이전의미해결과제들을전경으로떠' || char(10) || 'B. 자신이억압하고차단해왔던욕구와감정을알아차리는단계→차단되어왔 던에너지의파괴력이외부로발산하지못하고내부로향한다.' || char(10) || 'C. 역할연기를그만두고자립을시도하지만심한공포를체험하는단계 →견뎌내면유기체적인변화가일어나며새로운돌파구가열린다.' || char(10) || 'D. 사람들이서로형식적․의례적규범에따라피상적으로만나는단계', 'D', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
