INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''내담자의문제를밝히고이해하며해결하는데있어상담자가창의적인아이디어를구상하 여내담자와함께하나의상황을연출해냄으로써문제해결을돕는기법이다.''에 해당하는 것은?' || char(10) || 'A. 실험' || char(10) || 'B. 알아차림 연속' || char(10) || 'C. 통찰과 의미 발견' || char(10) || 'D. 빈 의자 기법', 'A', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''실험''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 현재화기법에서더나아가내담자가자신에게중요했던과거의어떤장면이나혹은미래에 있을수있는장면들을현재상황이벌어지는장면으' || char(10) || 'B. 내담자의문제를밝히고이해하며해결하는데있어상담자가창의적인아이디어를구상하 여내담자와함께하나의상황을연출해냄으로써문' || char(10) || 'C. 내담자는흔히자신의상상이나투사를현실과혼동하기때문에여러가지어려움을겪 는다.이때상담자는현실검증,즉현실이상상하' || char(10) || 'D. 내담자가문제극복체험을통하여자신의문제에대해서는물론,삶의전반에 대해이제까지와는다른새로운조망을얻게되고,따라서', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''과거사건을마치지금여기에서일어나는사건인것처럼체험하게해줌으로써과거 사건과관련된내담자의생각이나감정,욕구,환상,행동등을지금여기에일어나는현상들로다...''에 해당하는 것은?' || char(10) || 'A. 빈 의자 기법' || char(10) || 'B. 현실 검증' || char(10) || 'C. 과장하기' || char(10) || 'D. 현재화 기법', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''현재화 기법''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자로하여금자신의양극성의소외된측면들을접촉하여이를개발통합하도 록도와주는기법이다.' || char(10) || 'B. 내담자의 어떤 행동이나 언어를 과장하여 표현하도록 요구함으로써 내담자로 하여금 자신의무의식적욕구나감정혹은행' || char(10) || 'C. 내담자로하여금자신의미해결감정들을회피하지않고직면하여견뎌냄으로써이 를해소하도록돕는기법이다.' || char(10) || 'D. 과거사건을마치지금여기에서일어나는사건인것처럼체험하게해줌으로써과거 사건과관련된내담자의생각이나감정,욕구,환상', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''현재화기법에서더나아가내담자가자신에게중요했던과거의어떤장면이나혹은미래에 있을수있는장면들을현재상황이벌어지는장면으로상상하면서어떤행동을실제로연출해보 는...''에 해당하는 것은?' || char(10) || 'A. 현실 검증' || char(10) || 'B. 실연' || char(10) || 'C. 직면' || char(10) || 'D. 실험', 'B', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''실연''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자가문제극복체험을통하여자신의문제에대해서는물론,삶의전반에 대해이제까지와는다른새로운조망을얻게되고,따라서' || char(10) || 'B. 한가지현상에집중하여,현상이계속이어지는과정에서중요한것을연상하고, 연속적으로떠오르는전경하나하나를놓치지않고모' || char(10) || 'C. 현재화기법에서더나아가내담자가자신에게중요했던과거의어떤장면이나혹은미래에 있을수있는장면들을현재상황이벌어지는장면으' || char(10) || 'D. 과거사건을마치지금여기에서일어나는사건인것처럼체험하게해줌으로써과거 사건과관련된내담자의생각이나감정,욕구,환상', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''내담자는흔히자신의상상이나투사를현실과혼동하기때문에여러가지어려움을겪 는다.이때상담자는현실검증,즉현실이상상하는것과반드시일치하지않는다는사실을알아 ...''에 해당하는 것은?' || char(10) || 'A. 현실 검증' || char(10) || 'B. 빈 의자 기법' || char(10) || 'C. 실연' || char(10) || 'D. 실험', 'A', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''현실 검증''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 꿈은우리자신의일부를외부로투사한것으로본다.꿈은투사를되찾는데도움을주는 좋은소재가된다.투사된것들을다시찾기위해' || char(10) || 'B. 내담자가자기자신이투사행위의주체임을자각하도록돕는기법이다.내담자 의동의를얻고자신의병적투사물을시연해보라는투사' || char(10) || 'C. 내담자가문제극복체험을통하여자신의문제에대해서는물론,삶의전반에 대해이제까지와는다른새로운조망을얻게되고,따라서' || char(10) || 'D. 내담자는흔히자신의상상이나투사를현실과혼동하기때문에여러가지어려움을겪 는다.이때상담자는현실검증,즉현실이상상하', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''자신혹은타인과의관계를지금-여기에서다루기위해빈의자를사용하는기법이 다.게슈탈트심리상담에서가장많이쓰이는방법중하나로현재화,실연,현실검증의개념이모...''에 해당하는 것은?' || char(10) || 'A. 빈 의자 기법' || char(10) || 'B. 통찰과 의미 발견' || char(10) || 'C. 실험' || char(10) || 'D. 현재화 기법', 'A', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''빈 의자 기법''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자가문제극복체험을통하여자신의문제에대해서는물론,삶의전반에 대해이제까지와는다른새로운조망을얻게되고,따라서' || char(10) || 'B. 과거사건을마치지금여기에서일어나는사건인것처럼체험하게해줌으로써과거 사건과관련된내담자의생각이나감정,욕구,환상' || char(10) || 'C. 자신혹은타인과의관계를지금-여기에서다루기위해빈의자를사용하는기법이 다.게슈탈트심리상담에서가장많이쓰이는방법중하' || char(10) || 'D. 현재화기법에서더나아가내담자가자신에게중요했던과거의어떤장면이나혹은미래에 있을수있는장면들을현재상황이벌어지는장면으', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('상담기법에서 ''내담자는자신의진정한욕구나감정을회피해버림으로써미해결과제들을쌓아가는데,상 담자가내담자의이러한회피행동을지적하는동시에자신의진정한동기를 직면시켜줌으로...''에 해당하는 것은?' || char(10) || 'A. 직면' || char(10) || 'B. 알아차림 연속' || char(10) || 'C. 실험' || char(10) || 'D. 실연', 'A', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''직면''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자의문제를밝히고이해하며해결하는데있어상담자가창의적인아이디어를구상하 여내담자와함께하나의상황을연출해냄으로써문' || char(10) || 'B. 한가지현상에집중하여,현상이계속이어지는과정에서중요한것을연상하고, 연속적으로떠오르는전경하나하나를놓치지않고모' || char(10) || 'C. 내담자는자신의진정한욕구나감정을회피해버림으로써미해결과제들을쌓아가는데,상 담자가내담자의이러한회피행동을지적하는' || char(10) || 'D. 내담자로하여금자신의미해결감정들을회피하지않고직면하여견뎌냄으로써이 를해소하도록돕는기법이다.', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('주요개념에서 ''내담자로 하여금 자기제한적이고 자기패배적인 자신의 인생각본을 깨닫게 하고 더욱 적절하고 효율적인 대안을 찾게 하여 자율성을 획득하게 하는 것 ...''에 해당하는 것은?' || char(10) || 'A. 스트로크 ① 스트로크' || char(10) || 'B. 인생각본 ① 각본분석' || char(10) || 'C. 욕구(동기) ① 인정자극의 욕구' || char(10) || 'D. 라켓감정과 스템프 ① 라켓감정', 'B', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''인생각본 ① 각본분석''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자로 하여금 자기제한적이고 자기패배적인 자신의 인생각본을 깨닫게 하고 더욱 적절하고 효율적인 대안을 찾' || char(10) || 'B. 어른이 되어 스트레스 상황에서 각본을 실행할 때 현재 느끼는 실제적인 감정을 어린 시절 허락되었던 감정으로' || char(10) || 'C. 인정자극(다른 존재로부터 나의 존재가 인식되는 것)을 받으려는 욕구 ② 생활시간 구조에 대한 욕구:인정자' || char(10) || 'D. 언어적으로나 비언어적으로 교류를 할 때 주고받는 자극과 반응으로,인정의 한 단위 ② 스트로크 기아상태:', 'A', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
