INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''자동적 사고''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 심리적 문제를 초래하는 비효율적이고 부정적인 인지구조의 틀' || char(10) || 'B. 생활사건을 나름대로 해석하여 자동적 사고를 만들어 내는 인지적 과정의 잘못을 의미한다. þ 역기능적신념의구' || char(10) || 'C. 어떤 사건을 접했을 때 순간적으로 떠오르는 생각' || char(10) || 'D. 삶에 대한 일반적인 믿음이나 원칙으로 절대주의적이고 완벽주의적이며 융통 성이 없이 경직된 내용으로 구성되어', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
