INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''인지적 오류''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 생활사건을 나름대로 해석하여 자동적 사고를 만들어 내는 인지적 과정의 잘못을 의미한다. þ 역기능적신념의구' || char(10) || 'B. 심리적 문제를 초래하는 비효율적이고 부정적인 인지구조의 틀' || char(10) || 'C. 어떤 사건을 접했을 때 순간적으로 떠오르는 생각' || char(10) || 'D. 삶에 대한 일반적인 믿음이나 원칙으로 절대주의적이고 완벽주의적이며 융통 성이 없이 경직된 내용으로 구성되어', 'A', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('인지치료 기법에서 ''Ellis가제시한 A-B-C기법을 사용하여 종이 위에 사건 및 상황과 그때 의 감정 및 행동반응을 적어놓고 그 사이에 어떤 생각이 개입되어...''에 해당하는 것은?' || char(10) || 'A. 역기능적 사고 기록지' || char(10) || 'B. 탈파국화' || char(10) || 'C. 활동계획표 사용' || char(10) || 'D. 행동실험', 'A', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''역기능적 사고 기록지''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 직접 어려움을 호소하는 상황에 노출되어 보게 하여,불안한 사고에 도전할 수 있도 록 한다.' || char(10) || 'B. 파국화에서 벗어나도록 돕는 기법으로 내담자가 걱정하고 염려하여 사건을 지나치 게 파국화시키는 경우 내담자가' || char(10) || 'C. Ellis가제시한 A-B-C기법을 사용하여 종이 위에 사건 및 상황과 그때 의 감정 및 행동반응을 적어' || char(10) || 'D. 문제를 보다 구체적이고 개인적으로 만들고 내담자 자신의 관점에서 말할 수 있도록 돕는 기법이다.', 'C', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('인지치료 기법에서 ''자동적 사고의 기저에 존재하는 역기능적 신념을 탐색하는 기법으로,특정한 사건의 자동적 사고로부터 그 사고의 기저에 있는 신념내용을 계속 추적...''에 해당하는 것은?' || char(10) || 'A. 절대성에 도전하기' || char(10) || 'B. 행동실험' || char(10) || 'C. 하향 화살표 기법' || char(10) || 'D. 사고 중지', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''하향 화살표 기법''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 내담자로 하여금 실제로 그러한 행동을 해보고 어떤 결과가 나타나는지를 확인하는 일종의 실험을 해보는 것이다' || char(10) || 'B. 자동적 사고의 기저에 존재하는 역기능적 신념을 탐색하는 기법으로,특정한 사건의 자동적 사고로부터 그 사고' || char(10) || 'C. Ellis가제시한 A-B-C기법을 사용하여 종이 위에 사건 및 상황과 그때 의 감정 및 행동반응을 적어' || char(10) || 'D. 매일 시간대별로 구체적인 활동 계획을 기록하고 그 실행결과를 기록하는 간단한 표를 의미한다. (16)과제', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('인지치료 기법에서 ''한 상황에서 발생하는 모든 변인에 대한 검토를 요구함으로써 검증과 적당한 책임 할 당을 촉진시키는 기법이다.''에 해당하는 것은?' || char(10) || 'A. 재정의' || char(10) || 'B. 재귀인' || char(10) || 'C. 대처카드' || char(10) || 'D. 탈파국화', 'B', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''재귀인''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 파국화에서 벗어나도록 돕는 기법으로 내담자가 걱정하고 염려하여 사건을 지나치 게 파국화시키는 경우 내담자가' || char(10) || 'B. 상담자가 내담자로 하여금 자신의 부정적 사고,그 속에 포함된 논리적 오류,그 리고 대안적인 사고를 발견' || char(10) || 'C. 문제를 보다 구체적이고 개인적으로 만들고 내담자 자신의 관점에서 말할 수 있도록 돕는 기법이다.' || char(10) || 'D. 한 상황에서 발생하는 모든 변인에 대한 검토를 요구함으로써 검증과 적당한 책임 할 당을 촉진시키는 기법이다', 'D', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('인지치료 기법에서 ''파국화에서 벗어나도록 돕는 기법으로 내담자가 걱정하고 염려하여 사건을 지나치 게 파국화시키는 경우 내담자가 두려워하는 일이 실제로 어느 정도 ...''에 해당하는 것은?' || char(10) || 'A. 노출치료' || char(10) || 'B. 재정의' || char(10) || 'C. 재귀인' || char(10) || 'D. 탈파국화', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''탈파국화''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 지속되는 해로운 생각들을 없애는 데 어려움을 경험하는 경우,원치 않는 생각이 떠오를 때마다 “멈춰!”라고' || char(10) || 'B. Ellis가제시한 A-B-C기법을 사용하여 종이 위에 사건 및 상황과 그때 의 감정 및 행동반응을 적어' || char(10) || 'C. 파국화에서 벗어나도록 돕는 기법으로 내담자가 걱정하고 염려하여 사건을 지나치 게 파국화시키는 경우 내담자가' || char(10) || 'D. 상담자가 내담자로 하여금 자신의 부정적 사고,그 속에 포함된 논리적 오류,그 리고 대안적인 사고를 발견', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('인지치료 기법에서 ''타인의 관심이 자신에게 집중되어 있다는 잘못된 신념으로 불안해하는 내담자를 상 담하는 데 사용되는 기법으로,왜 타인이 자신을 응시하고 자신의...''에 해당하는 것은?' || char(10) || 'A. 사고 중지' || char(10) || 'B. 재정의' || char(10) || 'C. 하향 화살표 기법' || char(10) || 'D. 탈중심화', 'D', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''탈중심화''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 타인의 관심이 자신에게 집중되어 있다는 잘못된 신념으로 불안해하는 내담자를 상 담하는 데 사용되는 기법으로' || char(10) || 'B. 내담자로 하여금 실제로 그러한 행동을 해보고 어떤 결과가 나타나는지를 확인하는 일종의 실험을 해보는 것이다' || char(10) || 'C. 내담자의 절대적 진술에 대해 상담자는 질문을 통해 내담자가 보다 정확하 고 구체적으로 표현할 수 있도록 돕' || char(10) || 'D. 상담자가 내담자로 하여금 자신의 부정적 사고,그 속에 포함된 논리적 오류,그 리고 대안적인 사고를 발견', 'A', 'multiple-choice', 'subnote', 2, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('인지치료 기법에서 ''지속되는 해로운 생각들을 없애는 데 어려움을 경험하는 경우,원치 않는 생각이 떠오를 때마다 “멈춰!”라고 크게 혹은 목소리를 거의 내지 않고...''에 해당하는 것은?' || char(10) || 'A. 재정의' || char(10) || 'B. 절대성에 도전하기' || char(10) || 'C. 사고 중지' || char(10) || 'D. 소크라테스식 대화', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));
INSERT INTO Question (content, modelAnswer, type, source, difficulty, subjectId, pageRef, createdAt) VALUES ('''사고 중지''에 대한 설명으로 옳은 것은?' || char(10) || 'A. 부적응적인 자동적 사고에 대항하는 적응적 사고의 내용을 기록한 카드로서 내담자가 늘 지니고 다니거나 쉽게 ' || char(10) || 'B. 직접 어려움을 호소하는 상황에 노출되어 보게 하여,불안한 사고에 도전할 수 있도 록 한다.' || char(10) || 'C. 지속되는 해로운 생각들을 없애는 데 어려움을 경험하는 경우,원치 않는 생각이 떠오를 때마다 “멈춰!”라고' || char(10) || 'D. 내담자는 신념의 ‘감정적’부분의 역할을 맡고,치료자는 ‘이성적’부분 의 역할을 맡아,두 입장을 충분', 'C', 'multiple-choice', 'subnote', 3, 10, '', datetime('now'));